  tool_bmr_tdee_references:
    'Materi edukasi NCBI Bookshelf tentang metabolisme; sumber edukasi NHLBI tentang berat badan; rumus standar Mifflin / Harris / Katch.',
  tool_bmr_tdee_result_note: 'Perkiraan edukasi — bukan saran medis atau diet.',
