  tool_ip_range_to_cidr_article:
    'Ubah ekspor ACL berformat awal–akhir menjadi daftar CIDR siap tempel. IPv4 dan IPv6 jangan dicampur dalam satu batch.',
  tool_ip_range_to_cidr_clear: 'Hapus',
