  tool_ipv6_cidr_example:
    'Masukan: 2001:db8:1::/64. Keluaran: jaringan 2001:db8:1:: (panjang 2001:0db8:0001:0000:0000:0000:0000:0000), terakhir 2001:db8:1:0:ffff:ffff:ffff:ffff, jumlah 2^64, nibble selaras ya.',
